/// represents the state of a single button.
#[derive(Debug, Copy, Clone, PartialEq, Eq)]
#[repr(u8)]
pub enum ButtonEventKind {
    Down = 1,
    Up   = 2,
    Held = 3,
}

/// represents a single button event. `pin` is the pin number the button is associated with, and
/// `event` is the state of the button (whether it was pressed down this tick, let go this tick, or
/// held down.)
#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub struct ButtonEvent {
    pub pin:   i32,
    pub event: ButtonEventKind,
}

impl fmt::Display for ButtonEvent {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.event {
            ButtonEventKind::Down => write!(f, "({}, Down)", self.pin),
            ButtonEventKind::Up => write!(f, "({}, Up)", self.pin),
            ButtonEventKind::Held => write!(f, "({}, Held)", self.pin),
        }
    }
}

// ---------------------------------------------------------------------------
// Debounce state
// ---------------------------------------------------------------------------

// used for the convolution inside the debouncer
const MASK: u16 = 0b1111000000111111;

/// This is the debouncing state machine. Create one debouncing state machine per pin.
/// `Debounce::update_button` should be called every tick.
struct Debounce<'a> {
    inverted:   bool,
    history:    u16,
    down_time:  u64,
    next_long_time: u64,
    pin: Box<Input<'a>>,
    pintype: i32, // TODO: make this a proper enum
}

impl Debounce<'_> {
    /// Updates the state of the button. Should be called every tick.
    fn update_button(&mut self) {
        // level: 1 = high, 0 = low
        let level = self.pin.is_high();
        self.history = (self.history << 1) | if level { 1 } else { 0 };
    }

    /// Polls the button to see if it has risen this tick.
    fn button_rose(&mut self) -> bool {
        if (self.history & MASK) == 0b0000000000111111 {
            self.history = 0xffff;
            true
        } else {
            false
        }
    }

    /// Polls the button to see if it has fallen this tick.
    fn button_fell(&mut self) -> bool {
        if (self.history & MASK) == 0b1111000000000000 {
            self.history = 0x0000;
            true
        } else {
            false
        }
    }

    /// polls the button to see if it has been pressed down this tick.
    fn button_down(&mut self) -> bool {
        if self.inverted { self.button_fell() } else { self.button_rose() }
    }

    /// polls the button to see if it has been released up this tick.
    fn button_up(&mut self) -> bool {
        if self.inverted { self.button_rose() } else { self.button_fell() }
    }
}

