#[embassy_executor::task]
async fn listen_button(mut debounces: Vec<Debounce<'static>>) {
    // let timer = TimerDriver::new(timerg, &TimerConfig::new()).unwrap();
    let instant = Instant::now();
    let mut delay = Delay::new();
    let event_sender = CHANNEL.sender();
    loop {
        // let time = timer.counter().unwrap();
        // let now_ms = (1000 * time) / timer.tick_hz();
        let now_ms = instant.duration_since_epoch().as_millis();

        for d in debounces.iter_mut() {
            d.update_button();

            if d.button_up() {
                d.down_time = 0;
                let ev = ButtonEvent { pin: d.pintype, event: ButtonEventKind::Up };
                // let _ = queue_task.push(ev.into());
                event_sender.send(ev).await;
            } else if d.down_time != 0 && now_ms >= d.next_long_time {
                let ev = ButtonEvent { pin: d.pintype, event: ButtonEventKind::Held };
                // let _ = queue_task.push(ev.into());
                event_sender.send(ev).await;
                d.next_long_time += LONG_PRESS_REPEAT_MS;
            } else if d.button_down() && d.down_time == 0 {
                d.down_time = now_ms;
                d.next_long_time = now_ms + LONG_PRESS_DURATION_MS;
                let ev = ButtonEvent { pin: d.pintype, event: ButtonEventKind::Down };
                event_sender.send(ev).await;
                // let _ = queue_task.push(ev.into());
            }
        }

        // 10 ms delay – same as the original 10 / portTICK_PERIOD_MS
        // esp_idf_hal::delay::FreeRtos::delay_ms(10);
        delay.delay_ms(1000 as u32);
    }
}

